import { z } from 'zod'
import { Slug } from './common'

/**
 * Identifier prefixes (D25). Bodies are UUIDv7 generated by core/ids.ts; contracts only
 * check the prefix and a URL-safe body so they never depend on the generator's encoding.
 */
export const ID_PREFIXES = {
  workspace: 'ws',
  connection: 'con',
  apiKey: 'key',
  override: 'ovr',
  template: 'tpl',
  blob: 'blob',
  message: 'msg',
  recipient: 'rcp',
  attachment: 'att',
  event: 'evt',
  suppression: 'sup',
  webhookEndpoint: 'whe',
  webhookDelivery: 'whd',
  apiLog: 'req',
  smtpSession: 'smtp',
} as const

export type IdPrefix = (typeof ID_PREFIXES)[keyof typeof ID_PREFIXES]

export function prefixedId<P extends IdPrefix>(prefix: P) {
  return z
    .string()
    .regex(
      new RegExp(`^${prefix}_[A-Za-z0-9-]{1,64}$`),
      `Expected an id starting with "${prefix}_"`,
    )
}

export const WorkspaceId = prefixedId('ws')
export const ConnectionId = prefixedId('con')
export const OverrideId = prefixedId('ovr')
export const MessageId = prefixedId('msg')
export const AttachmentId = prefixedId('att')
export const EventId = prefixedId('evt')
export const WebhookEndpointId = prefixedId('whe')
export const WebhookDeliveryId = prefixedId('whd')

/** Workspace reference accepted by `:id` and `X-Mailsink-Workspace`: id or slug. */
export const WorkspaceRef = z.union([WorkspaceId, Slug])

/** Secret prefixes: connection keys, workspace keys (D12), webhook secrets (D11). */
export const KEY_PREFIXES = { connection: 'msk_', workspace: 'mskw_', webhook: 'whsec_' } as const

export const ConnectionKey = z.string().regex(/^msk_[A-Za-z0-9_-]{16,128}$/, 'Invalid msk_ key')
export const WorkspaceKey = z.string().regex(/^mskw_[A-Za-z0-9_-]{16,128}$/, 'Invalid mskw_ key')

/** Kind of a bearer token from its prefix, or null when it is not a Mailsink key. */
export function keyKind(token: string): 'connection' | 'workspace' | null {
  if (WorkspaceKey.safeParse(token).success) return 'workspace'
  if (ConnectionKey.safeParse(token).success) return 'connection'
  return null
}
